import{_ as t,o,c as r,a6 as s}from"./chunks/framework.CCKCzdWs.js";const g=JSON.parse(`{"title":"Record tests from the editor","description":"Record a Playwright test from VS Code or a JetBrains IDE: a browser your project's own Playwright opens, and each step you take there written at the cursor as you go, with locators verified on the page and calls to your own page objects.","frontmatter":{"title":"Record tests from the editor","description":"Record a Playwright test from VS Code or a JetBrains IDE: a browser your project's own Playwright opens, and each step you take there written at the cursor as you go, with locators verified on the page and calls to your own page objects.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-recording.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-recording.html"}],["meta",{"property":"og:title","content":"Record tests from the editor | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Record a Playwright test from VS Code or a JetBrains IDE: a browser your project's own Playwright opens, and each step you take there written at the cursor as you go, with locators verified on the page and calls to your own page objects."}]]},"headers":[],"relativePath":"features/editor-recording.md","filePath":"features/editor-recording.md","lastUpdated":1793126428000}`),a={name:"features/editor-recording.md"};function i(n,e,d,h,c,l){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="record-tests-from-the-editor" tabindex="-1">Record tests from the editor <a class="header-anchor" href="#record-tests-from-the-editor" aria-label="Permalink to &quot;Record tests from the editor&quot;">​</a></h1><p><strong>Piwi: Record here</strong> opens a browser through your project&#39;s own Playwright and writes what you do there at the cursor, as you do it: steps inside a test, a page object&#39;s method or a helper function, a new test anywhere else in a spec. It works in VS Code (and Cursor, VSCodium) and in the JetBrains IDEs with the <a href="./jetbrains.html">Piwi plugin</a>, and needs no instance, no desktop app and no browser extension.</p><h2 id="start-a-recording" tabindex="-1">Start a recording <a class="header-anchor" href="#start-a-recording" aria-label="Permalink to &quot;Start a recording&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Editor</th><th>Record at the cursor</th><th>Record a new test file</th></tr></thead><tbody><tr><td>VS Code</td><td><strong>Piwi: Record here</strong>, from the command palette or the editor&#39;s context menu</td><td><strong>Piwi: Record a new test file</strong></td></tr><tr><td>JetBrains IDE</td><td><strong>Tools → Piwi → Record Here</strong>, <strong>Alt+Enter</strong> or <strong>Alt+Insert</strong> (Generate), or the editor&#39;s context menu</td><td><strong>File → New → Record a New Test File…</strong></td></tr></tbody></table><p>Before the browser opens, the editor asks for:</p><ol><li><strong>The start page</strong>: a path on the project&#39;s <code>baseURL</code>, or an address; left empty, the browser opens the <code>baseURL</code>.</li><li><strong>The page the steps run on</strong>, when the code around the cursor offers several: <code>page</code>, a fixture such as <code>adminPage</code>, or <code>this.page</code> in a page object. A fixture named like a page object (<code>todoPage</code>) comes after <code>page</code> until the test calls a page method on it. Any other expression can be typed.</li><li><strong>The Playwright project</strong>, when the config has several. The browser gets its <code>use</code> options: <code>baseURL</code>, <code>storageState</code>, the viewport and device, the locale, the extra headers and <code>testIdAttribute</code>.</li></ol><p>The editor offers your last answers again. A new test file is offered next to the file you are in, and the recording writes a whole spec into it.</p><h2 id="while-it-records" tabindex="-1">While it records <a class="header-anchor" href="#while-it-records" aria-label="Permalink to &quot;While it records&quot;">​</a></h2><ul><li><strong>The block</strong> the recording writes is tinted, and written again as each step arrives: a run of steps becomes one call to your own page object or helper once its last step is recorded. Started on a line inside a call that spans several lines, the block goes after that statement.</li><li><strong>The controls</strong>: the step count, <strong>Stop</strong> and <strong>Pause</strong> (<strong>Resume</strong> while paused), above the block in VS Code and in a banner above the editor in a JetBrains IDE, and <strong>Pause</strong>, <strong>Stop</strong> and the checks in the browser&#39;s recording bar. The status bar shows the recording too. While paused, from the editor or the browser, what you do in the browser is not recorded: use it to reach a page or set up data without writing those steps; <strong>Resume</strong> continues from there.</li><li><strong>Checks</strong>: <strong>Check an element</strong> in the browser&#39;s recording bar lets you pick an element and check its text, its value, its accessible name or its state, starting from what it shows now; <strong>Check the address</strong> checks the page&#39;s address. Each is written as an <code>await expect(…)</code> where you added it.</li><li><strong>Typing in the block</strong> pauses the recording. <strong>Resume</strong> writes the block again from the recorded steps, over your edits; <strong>Keep my edits</strong> stops the recording and keeps the code as you changed it.</li><li><strong>Warnings</strong> (a brittle locator, a password read from the environment, a file to upload) are on their lines. They stay after the recording, each until its line is edited.</li></ul><p>What the code holds, from locators to imports, and the options in the Playwright config that shape it: <a href="./recorded-code.html">Recorded code</a>.</p><h2 id="stop-and-undo" tabindex="-1">Stop and undo <a class="header-anchor" href="#stop-and-undo" aria-label="Permalink to &quot;Stop and undo&quot;">​</a></h2><p><strong>Stop</strong> in the editor or in the browser&#39;s recording bar, or closing the browser, ends the recording, and the code stays. Closing the file ends it too. One <strong>Undo</strong> then removes the whole recording, imports included. In VS Code, a save or an edit of the file during the recording starts a new undo step, so your own changes stay undoable on their own; in a JetBrains IDE, that Undo also takes back the edits you made in the file meanwhile, and Redo brings everything back.</p><h3 id="run-it-or-verify-it-three-times" tabindex="-1">Run it, or verify it three times <a class="header-anchor" href="#run-it-or-verify-it-three-times" aria-label="Permalink to &quot;Run it, or verify it three times&quot;">​</a></h3><p>Once the recording stopped, a notification says what it wrote, <code>Recorded 6 steps into checkout.spec.ts.</code>, with two actions for the test that holds the block, the new test or the test you recorded steps into:</p><ul><li><strong>Run</strong> runs that test, with your breakpoints, as <strong>Piwi: Run the test at the cursor</strong> does.</li><li><strong>Verify ×3</strong> runs it three times, without retries and without the breakpoints, as <strong>Piwi: Verify the test at the cursor ×3</strong> does, and says how it went: <code>Passed 3 of 3</code>, or <code>Failed 1 of 3</code> with <strong>Open the failures</strong> and <strong>Open in dashboard</strong>.</li></ul><p>Both save the file, then run the test by the line of its <code>test(…)</code> call (<code>npx playwright test tests/checkout.spec.ts:42</code>), so neither needs an instance: <a href="./editor-runs.html#when-your-run-ends">When your run ends</a> says how a run without one is counted. Steps recorded into a page object or a helper offer neither action: no test holds them.</p><h3 id="choose-another-locator" tabindex="-1">Choose another locator <a class="header-anchor" href="#choose-another-locator" aria-label="Permalink to &quot;Choose another locator&quot;">​</a></h3><p>The recorder keeps up to five locators for each element it acts on, each verified to find that element alone on the page, and writes the best one. Once the recording stopped, a warning on a step that has other locators offers each of them as a quick fix, best first: <strong>Use getByTestId(&#39;pay&#39;)</strong> in the light bulb menu in VS Code, with <strong>Alt+Enter</strong> in a JetBrains IDE. It puts that locator in place of the one written on the line, as one edit that <strong>Undo</strong> takes back, and the line&#39;s warning goes. While the recording runs, none is offered: each step writes the block again.</p><p>The quick fix replaces the locator only where the line holds it once, as it was written: a line that calls your own page object or helper has none of its own, and offers none.</p><h2 id="send-from-piwi-picker" tabindex="-1">Send from Piwi Picker <a class="header-anchor" href="#send-from-piwi-picker" aria-label="Permalink to &quot;Send from Piwi Picker&quot;">​</a></h2><p>A locator picked with the <a href="./extension.html">Piwi Picker</a> browser extension in your everyday browser, or a flow it recorded, lands at the editor&#39;s cursor too:</p><ol><li>In the editor, run <strong>Piwi: Pair with Piwi Picker</strong> (<strong>Tools → Piwi → Pair with Piwi Picker</strong> in a JetBrains IDE). It copies a pairing address, <code>http://127.0.0.1:&lt;port&gt;/…#&lt;token&gt;</code>.</li><li>In Piwi Picker&#39;s settings, paste it under <strong>Send to editor</strong> and click <strong>Pair</strong>; the browser asks once for access to that local address.</li><li>A picked locator&#39;s row, the top locator of the <a href="./devtools.html#the-elements-sidebar">Elements sidebar</a>, the <a href="./devtools.html#the-piwi-panel">Locators console</a> in DevTools and the recording review then show <strong>Send to editor</strong>. A locator is inserted in the copy form you chose; a recording is rendered as the body of a test, like <a href="/reference/cli.html#codegen"><code>piwi codegen --body</code></a>.</li></ol><p>The editor listens on the loopback interface only, answers only a request addressed to <code>127.0.0.1</code> or <code>localhost</code> at its port, and accepts one only with the token. Before Piwi Picker sends the token, the editor proves it holds it, so another program that took the port is sent nothing. With several VS Code windows open, the one that paired receives. With no editor open, a JetBrains IDE puts it in a new scratch file. In a remote window (Remote SSH, WSL, Dev Containers), the pairing address is the local end of a port VS Code forwards to the listener, listed in the Ports view; Piwi Picker&#39;s Runs window lists no run of a remote window yet.</p><p>Every test run Piwi starts gets the pairing address and token as <code>PIWI_EDITOR_SEND</code>, so a locator picked at one of its stops reaches the editor: such a run starts the listener and creates the token if there is none. The capture fixtures hide it from the processes a test starts; the Playwright runner and its <code>webServer</code> still have it, and programs running as your user are not kept out.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>The browser is the one your tests use, installed by Playwright (<code>npx playwright install chromium</code>).</li><li>Your project&#39;s Playwright runs with the first <code>node</code> on the editor&#39;s <code>PATH</code> in VS Code (when it is Node 20 or later, else with the editor&#39;s own runtime), and with the project&#39;s Node.js interpreter in a JetBrains IDE.</li><li>The recording does not start your <code>webServer</code>: start the application first.</li><li>It records the top-level page: clicks inside an iframe, and steps in a popup or a new tab, are not recorded yet. The editor says so when the application opens a tab or a popup.</li><li>A file takes one recording at a time.</li><li>A recording starts on a fresh page. To record where a test already is (signed in, halfway through a flow), pause the test there and <a href="./editor-breakpoints.html#record-from-a-pause">record from the pause</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./recorded-code.html">Recorded code</a>: what a recording writes, and the options that shape it.</li><li><a href="./editors.html">Editor extensions</a>: everything else the editor shows from your suite.</li><li><a href="./extension.html">Piwi Picker</a>: records in your everyday browser, for a bug report or a steps file.</li><li><a href="./test-functions.html">Test functions</a>: the page objects and helpers a recording calls.</li></ul>',28)])])}const u=t(a,[["render",i]]);export{g as __pageData,u as default};
